[CmdletBinding()]
param()
$ErrorActionPreference='Stop';$cli=Join-Path $PSScriptRoot 'skill-discovery-metrics.ps1';$hostExe=(Get-Process -Id $PID).Path
$root=Join-Path ([IO.Path]::GetTempPath()) ('skill-metrics-'+[guid]::NewGuid().ToString('N'));$pass=0;$fail=0
function Assert-Check([bool]$ok,[string]$label){if($ok){Write-Host "[PASS] $label";$script:pass++}else{Write-Host "[FAIL] $label";$script:fail++}}
function Invoke-Cli([string[]]$cliArgs){$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=$script:hostExe;$psi.Arguments='-NoProfile -ExecutionPolicy Bypass -File "'+$script:cli+'" '+(($cliArgs|ForEach-Object{'"'+([string]$_).Replace('"','\"')+'"'}) -join ' ');$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=[Diagnostics.Process]::Start($psi);$out=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();$code=$p.ExitCode;$p.Dispose();$obj=$null;try{$obj=ConvertFrom-Json $out}catch{};return [pscustomobject]@{code=$code;out=$out;err=$err;json=$obj}}
function Invoke-TwoRoots([string]$first,[string]$second,[string[]]$other){$q1=$first.Replace("'","''");$q2=$second.Replace("'","''");$parts=@();foreach($v in $other){if($v.StartsWith('-')){$parts+=$v}else{$parts+=('"'+$v.Replace('"','\"')+'"')}};$expr="& '$script:cli' -SkillRoots @('$q1','$q2') $($parts -join ' ')";$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($expr));$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=$script:hostExe;$psi.Arguments='-NoProfile -ExecutionPolicy Bypass -EncodedCommand '+$encoded;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=[Diagnostics.Process]::Start($psi);$out=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();$code=$p.ExitCode;$p.Dispose();$obj=$null;try{$obj=ConvertFrom-Json $out}catch{};return [pscustomobject]@{code=$code;out=$out;err=$err;json=$obj}}
try{
 [void][IO.Directory]::CreateDirectory($root);$a=Join-Path $root 'a';$b=Join-Path $root 'b';[void][IO.Directory]::CreateDirectory($a);[void][IO.Directory]::CreateDirectory($b)
  $entries=@(@{r=$a;d='one';t="---`nname: alpha`ndescription: review code`n---`nBody $([char]0xE9)"},@{r=$a;d='two';t="---`nname: beta`ndescription: review findings`n---`nbody two"},@{r=$a;d='three';t="---`nname: gamma`ndescription: unrelated topic`n---`nbody three"},@{r=$a;d='bad';t='No frontmatter'},@{r=$a;d='open';t="---`nname: open`ndescription: no close"},@{r=$a;d='indented';t="---`n  name: hidden`nname: visible`ndescription: >`n---`nbody"},@{r=$a;d='beta-copy';t="---`nname: beta`ndescription: review findings`n---`nbody two"},@{r=$b;d='duplicate';t="---`nname: alpha`ndescription: review duplicate`n---`nbody duplicate"})
 foreach($e in $entries){$d=Join-Path $e.r $e.d;[void][IO.Directory]::CreateDirectory($d);[IO.File]::WriteAllText((Join-Path $d 'SKILL.md'),$e.t,[Text.Encoding]::UTF8)}
 # Exact raw-byte lengths after the closing delimiter for LF, CRLF, and BOM files.
 foreach($case in @(@{d='lf';nl="`n";bom=$false},@{d='crlf';nl="`r`n";bom=$false},@{d='bom';nl="`r`n";bom=$true})){$dir=Join-Path $a $case.d;[void][IO.Directory]::CreateDirectory($dir);$content='---'+$case.nl+'name: '+$case.d+$case.nl+'description: bytes'+$case.nl+'---'+$case.nl+'A'+[char]0xE9+'Z';$raw=[Text.Encoding]::UTF8.GetBytes($content);if($case.bom){$raw=@([byte]0xEF,[byte]0xBB,[byte]0xBF)+$raw};[IO.File]::WriteAllBytes((Join-Path $dir 'SKILL.md'),$raw)}
 $r=Invoke-Cli @('-SkillRoots',$a,'-Iterations','2','-Json');$j=$r.json
  Assert-Check (($r.code -eq 0)-and $j.ok -and $j.baseline.skills_total -eq 8 -and $j.baseline.invalid -eq 2) ('valid/invalid and unclosed frontmatter counts '+$r.out+' '+$r.err)
 Assert-Check (($j.skills|Where-Object{$_.name -eq 'visible'}).unsupported_frontmatter -and (($j.skills|Where-Object{$_.name -eq 'visible'}).metadata_chars -eq 7)) 'indented key ignored and block scalar marked unsupported'
 foreach($case in @(@{n='lf';tail=4},@{n='crlf';tail=4},@{n='bom';tail=4})){$actual=($j.skills|Where-Object{$_.name -eq $case.n}).body_bytes;Assert-Check ($actual -eq $case.tail) ($case.n+' raw body byte count '+$actual)}
  $two=Invoke-TwoRoots $a $b @('-Iterations','1','-Json');$j2=$two.json
  $alphaDup=$j2.duplicate_names|Where-Object name -eq 'alpha';$betaDup=$j2.duplicate_names|Where-Object name -eq 'beta'
  Assert-Check (($two.code -eq 0)-and $j2.roots.Count -eq 2 -and $alphaDup.occurrences -eq 2 -and $alphaDup.differs -and $betaDup.occurrences -eq 2 -and (-not $betaDup.differs) -and $j2.unique_name_totals.skills_total -eq ($j2.baseline.skills_total-2)) 'same-root and cross-root duplicates include hashes and unique totals'
  $target=Join-Path $root 'junction-target';$link=Join-Path $a 'junction-skill';[void][IO.Directory]::CreateDirectory($target);[IO.File]::WriteAllText((Join-Path $target 'SKILL.md'),"---`nname: linked-skill`ndescription: junction fixture`n---`nbody",[Text.Encoding]::UTF8)
  $junctionCreated=$false;try{$mk=Start-Process -FilePath $env:ComSpec -ArgumentList @('/c','mklink','/J',('"'+$link+'"'),('"'+$target+'"')) -Wait -PassThru -WindowStyle Hidden;$junctionCreated=($mk.ExitCode -eq 0 -and (Test-Path -LiteralPath $link))}catch{}
  if($junctionCreated){$follow=Invoke-Cli @('-SkillRoots',$a,'-Iterations','1','-Json');$strict=Invoke-Cli @('-SkillRoots',$a,'-Iterations','1','-SkipReparse','-Json');Assert-Check (($follow.json.followed_reparse -ge 1)-and($follow.json.baseline.skills_total -eq ($strict.json.baseline.skills_total+1))) 'default follows junction; strict mode skips it';Assert-Check ($strict.json.skipped_reparse -ge 1) 'SkipReparse reports skipped junction'}else{Write-Host 'SKIP: junction creation unavailable'}
 $s=Invoke-Cli @('-SkillRoots',$a,'-Query','review code changes findings','-Limit','1','-Iterations','1','-Json')
  Assert-Check (($s.json.selected.Count -eq 1)-and $s.json.selected[0].name -eq 'alpha' -and $s.json.selection_ratio_vs_unique -eq [Math]::Round($s.json.selected_metadata_tokens_est/[double]$s.json.unique_name_totals.metadata_tokens_est_total,4)) 'selection tie ordering and unique ratio'
 $miss=Invoke-Cli @('-SkillRoots',$a,'-Query','zzznomatch','-Iterations','1','-Json');Assert-Check ($miss.json.selected.Count -eq 0 -and $miss.json.selected_coverage -eq 0) 'no-match selection empty'
 $empty=Invoke-Cli @('-SkillRoots',$a,'-Query','','-Iterations','1','-Json');Assert-Check ($empty.json.selected.Count -eq 0) 'empty query does not select'
 $same1=Invoke-Cli @('-SkillRoots',$a,'-Iterations','1','-Json');$same2=Invoke-Cli @('-SkillRoots',$a,'-Iterations','1','-Json')
 $stable1=$same1.json|Select-Object * -ExcludeProperty timing|ConvertTo-Json -Depth 8 -Compress;$stable2=$same2.json|Select-Object * -ExcludeProperty timing|ConvertTo-Json -Depth 8 -Compress
 Assert-Check ($stable1 -ceq $stable2) 'JSON identical excluding nondeterministic timing block'
 Assert-Check (($same1.json.timing.scan_ms_p50 -eq $same1.json.timing.scan_ms_p95)-and($same1.json.timing.scan_ms_p95 -eq $same1.json.timing.scan_ms_max)) 'N=1 percentile values'
 $n2=Invoke-Cli @('-SkillRoots',$a,'-Iterations','2','-Json');Assert-Check (($n2.json.timing.scan_ms_p50 -le $n2.json.timing.scan_ms_p95)-and($n2.json.timing.scan_ms_p95 -eq $n2.json.timing.scan_ms_max)) 'N=2 p50/p95 order and maximum'
 $badL=Invoke-Cli @('-SkillRoots',$a,'-Limit','0','-Json');$badI=Invoke-Cli @('-SkillRoots',$a,'-Iterations','51','-Json');Assert-Check (($badL.code -eq 2)-and($badI.code -eq 2)) 'invalid ranges exit 2'
  $missing=Invoke-Cli @('-SkillRoots',(Join-Path $root 'missing'),'-Iterations','1','-Json');Assert-Check (($missing.code -eq 0)-and(-not $missing.json.roots[0].exists)-and$missing.json.ok) 'missing root represented without failure'
  $largeDir=Join-Path $a 'large';[void][IO.Directory]::CreateDirectory($largeDir);$largeBytes=New-Object byte[] (1MB+1);[IO.File]::WriteAllBytes((Join-Path $largeDir 'SKILL.md'),$largeBytes);$large=Invoke-Cli @('-SkillRoots',$a,'-Iterations','1','-Json');Assert-Check (($large.json.baseline.unreadable -eq 1)-and($large.json.roots[0].unreadable_reasons -contains 'too_large')) 'over-1MiB skill is unreadable with too_large reason'
}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
Write-Host ("Passed: $pass; Failed: $fail");if($fail){exit 1};exit 0
